@@ -5,7 +5,7 @@ pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
 void *writer_a(void *unused) {
     (void)unused;
     pthread_mutex_lock(&mutex);
-    counter++;
+    counter += 2;
     pthread_mutex_unlock(&mutex);
     return 0;
 }
@@ -18,9 +18,9 @@ void *writer_b(void *unused) {
 }
 int main(void) {
     pthread_t a, b;
